(function(){window.kentico.pageBuilder.registerInlineEditor("text-editor",{init:function(t){var e=t.editor;e.addEventListener("input",function(){this.textContent||(this.innerHTML="");var n=new CustomEvent("updateProperty",{detail:{name:t.propertyName,value:this.textContent,refreshMarkup:!1}});e.dispatchEvent(n)})}})})();
